// spawn a test makes is attributed no matter which module made it. A plain
// monkey-patch cannot do this: a builtin's named exports are snapshotted when the
// builtin first loads, so `import { spawnSync }` keeps the original binding.
export async function resolve(specifier, context, next) {
  if (specifier === 'node:child_process' || specifier === 'child_process') {
    if (!context.parentURL?.includes('cp-shim.mjs')) {
      return { url: new URL('./cp-shim.mjs', import.meta.url).href, shortCircuit: true };
    }
  }
  return next(specifier, context);
}
EOF
cat > $S/cp-shim.mjs <<'EOF'
import * as real from 'node:child_process';
const stats = globalThis.__CP_STATS ??= new Map();
const note = (kind, cmd, args, ms) => {
  const key = `${kind} ${cmd === process.execPath ? 'node' : cmd} ${Array.isArray(args) ? args.slice(0, 2).join(' ') : ''}`.trim();
  const e = stats.get(key) ?? { n: 0, ms: 0 };
  e.n++; e.ms += ms; stats.set(key, e);
};
const wrapSync = (kind, fn) => function (...a) {
  const s = process.hrtime.bigint();
  try { return fn.apply(this, a); }
  finally { note(kind, a[0], a[1], Number(process.hrtime.bigint() - s) / 1e6); }
};
export const spawnSync = wrapSync('spawnSync', real.spawnSync);
export const execFileSync = wrapSync('execFileSync', real.execFileSync);
export const execSync = wrapSync('execSync', real.execSync);
export const spawn = real.spawn;
export const execFile = real.execFile;
export const exec = real.exec;
export const fork = real.fork;
export const ChildProcess = real.ChildProcess;
export default { ...real, spawnSync, execFileSync, execSync };
process.on('exit', () => {
  const rows = [...stats].sort((a, b) => b[1].ms - a[1].ms);
  const tn = rows.reduce((s, [, v]) => s + v.n, 0), tms = rows.reduce((s, [, v]) => s + v.ms, 0);
  process._rawDebug(`CPSTATS\t${tn}\t${tms.toFixed(0)}`);
  for (const [k, v] of rows.slice(0, 12)) process._rawDebug(`CPROW\t${v.n}\t${v.ms.toFixed(0)}\t${k}`);
});
EOF
