// Does the rehearsal's CONDITIONAL second converge actually fire every time?
// The condition is "a migration note rewrote the declaration"; 148 invocations
// across 74 rehearsals says it fires 74/74. Read what changes.
import { readFileSync } from 'node:fs';
import { FIXTURES, MODES } from '/home/user/Claudinite/vendoring/rehearsal/fixtures.mjs';
import { buildFixture, CANON } from '/home/user/Claudinite/vendoring/rehearsal/rehearse.mjs';
import { settingsPath } from '/home/user/Claudinite/engine/settings-file.mjs';
import { removeTree } from '/home/user/Claudinite/engine/remove-tree.mjs';
import { promisify } from 'node:util';
import { execFile } from 'node:child_process';
import { join } from 'node:path';
const run = promisify(execFile);
let fired = 0, total = 0;
for (const fixture of FIXTURES.slice(0, 8)) {
  for (const mode of MODES) {
    const root = await buildFixture(fixture, mode);
    try {
      await run(process.execPath, [join(CANON, 'vendoring/apply-vendor-set.mjs'), '--target', root]);
      const before = readFileSync(settingsPath(root), 'utf8');
      await run(process.execPath, [join(CANON, 'engine/migrations/apply.mjs')], { env: { ...process.env, CLAUDE_PROJECT_DIR: root }, cwd: root });
      const after = readFileSync(settingsPath(root), 'utf8');
      total++;
      if (before !== after) {
        fired++;
        const b = JSON.parse(before), a = JSON.parse(after);
        const changed = [...new Set([...Object.keys(b), ...Object.keys(a)])].filter((k) => JSON.stringify(b[k]) !== JSON.stringify(a[k]));
        if (fired <= 4) console.log(`  ${fixture.name} [${mode.name}] re-converges; keys that changed: ${changed.join(', ') || '(only formatting)'}`);
      }
    } finally { removeTree(root); }
  }
}
console.log(`\nthe conditional second apply-vendor-set fired ${fired}/${total} times`);
EOF
node $S/reconverge.mjs

