const GIT_ENV = { ...process.env, GIT_AUTHOR_NAME: 'test', GIT_AUTHOR_EMAIL: 'test@test',
  GIT_COMMITTER_NAME: 'test', GIT_COMMITTER_EMAIL: 'test@test',
  GIT_CONFIG_COUNT: '3', GIT_CONFIG_KEY_0: 'gc.autoDetach', GIT_CONFIG_VALUE_0: 'false',
  GIT_CONFIG_KEY_1: 'maintenance.auto', GIT_CONFIG_VALUE_1: 'false',
  GIT_CONFIG_KEY_2: 'commit.gpgsign', GIT_CONFIG_VALUE_2: 'false' };
const git = (root, ...args) => { const r = spawnSync('git', args, { cwd: root, env: GIT_ENV, encoding: 'utf8' }); if (r.status !== 0) throw new Error(r.stderr); return r.stdout; };
const writeFiles = (root, files) => { for (const [p, c] of Object.entries(files)) { mkdirSync(join(root, dirname(p)), { recursive: true }); writeFileSync(join(root, p), c); } };

// verbatim the pre-change makeRepo
function makeRepoOld({ base = {}, changed = {}, commitMsg = 'change Refs #1', uncommitted = {} }) {
  const root = mkdtempSync(join(tmpdir(), 'claudinite-checks-'));
  git(root, 'init', '-q', '-b', 'main');
  writeFiles(root, { 'README.md': 'seed\n', ...base });
  git(root, 'add', '-A');
  git(root, 'commit', '-q', '-m', 'seed');
  git(root, 'checkout', '-q', '-b', 'feature');
  if (Object.keys(changed).length) { writeFiles(root, changed); git(root, 'add', '-A'); git(root, 'commit', '-q', '-m', commitMsg); }
  writeFiles(root, uncommitted);
  return root;
}

// Everything a check can observe, with the two things that MUST differ normalised away.
function snapshot(root, mode) {
  const ctx = buildContext({ root, mode });
  const plain = {};
  for (const k of Object.keys(ctx).sort()) {
    const v = ctx[k];
    if (typeof v === 'function') continue;
    plain[k] = v;
  }
  plain.__reads = Object.fromEntries(ctx.files.map((f) => [f, ctx.readFile ? ctx.readFile(f) : null]));
  plain.__deleted = ctx.deleted;
  plain.__addedLines = Object.fromEntries((ctx.changedFiles ?? []).map((f) => [f, JSON.stringify(ctx.addedLines ? ctx.addedLines(f) : null)]));
  return JSON.stringify(plain, (k, v) => (k === 'root' ? '<root>' : v), 1)
    .replaceAll(root, '<root>')
    .replace(/\b[0-9a-f]{40}\b/g, '<sha>');
}

const SHAPES = [
  { name: 'plain change', changed: { 'a.txt': 'x\n' } },
  { name: 'no change at all', },
  { name: 'nested + untracked', changed: { 'src/a.mjs': 'export const a = 1;\n' }, uncommitted: { 'scratch.txt': 'u\n' } },
  { name: 'custom commit message', changed: { 'a.txt': 'x\n' }, commitMsg: 'feat: something Refs #9' },
  { name: 'many files', changed: Object.fromEntries(Array.from({ length: 12 }, (_, i) => [`d${i}/f${i}.md`, `# ${i}\n`])) },
  { name: 'gitattributes vendored', changed: { '.gitattributes': 'vend/** linguist-vendored\n', 'vend/x.mjs': '1\n', 'own.mjs': '2\n' } },
  { name: 'with base files', base: { 'b.txt': 'base\n' }, changed: { 'a.txt': 'x\n' } },
  { name: 'dotfiles + gitignore', changed: { '.gitignore': 'ignored/\n', 'keep.txt': 'k\n' }, uncommitted: { 'ignored/skip.txt': 's\n', 'seen.txt': 'v\n' } },
];

let fails = 0;
for (const { name, ...shape } of SHAPES) {
  for (const mode of ['all', 'changed']) {
    const a = makeRepoOld(shape); const b = makeRepo(shape);
    let sa, sb;
    try { sa = snapshot(a, mode); sb = snapshot(b, mode); } finally { cleanup(a); cleanup(b); }
    if (sa === sb) { console.log(`  ok   ${name} [${mode}]`); }
    else {
      fails++; console.log(`  FAIL ${name} [${mode}]`);
      const la = sa.split('\n'), lb = sb.split('\n');
      for (let i = 0; i < Math.max(la.length, lb.length); i++) if (la[i] !== lb[i]) { console.log(`    old: ${la[i]}\n    new: ${lb[i]}`); break; }
    }
  }
}
console.log(fails ? `\n${fails} SHAPE(S) DIVERGED` : '\nevery shape: the new seeding path is bit-identical to the old');
process.exit(fails ? 1 : 0);
