// Signal collection for ONE task (docs/PRINCIPLES.md): exactly that
// task's declared union, collected at the moment a verdict is asked for. Two
// callers ask — the scheduler run at every tick (a read it cannot make fails open
// there) and the executor at pick, which re-derives rather than trusting the
// tick's answer forward.
//
// THE RUN HISTORY COMES FIRST, always: the `runs` bundle is what the cadence
// terms read, and it is also what sets the WINDOW every other collector reads
// over — since this task's newest run started, so a task reads exactly what moved
// since it last looked, and one that declined for a week then sees the week. With
// no run in the horizon the window is the task's own cadence (a day for a task
// stating none) plus an hour of slack. Overlap at the seam — a run's own duration
// — is absorbed by the preconditions' own dedupe, as the old fixed lookback's was.

import { itemFacts } from '../items/work-item.mjs';
import { taskSignalNames } from '../contract/task-contract.mjs';
import { DAY_MS, defaultWindowMs, windowDaysOf } from '../contract/precondition.mjs';

// Republished from the contract that owns them: a caller reading a task's window
// off its collected signals asks the collector, not two modules.
export { defaultWindowMs, windowDaysOf };

// The window, from the run history: `{ sinceIso, days }`. The newest run that
// actually ran — a `rejected` item declined at pick and did nothing, so it does not
// move the seam — anchors it at its start; none in the horizon falls back to the
// task's default.
export function windowFromRuns(task, runs, now) {
  const nowMs = new Date(now).getTime();
  const last = (runs?.list ?? []).find((r) => r.outcome !== 'obsolete');
  const sinceMs = last && Number.isFinite(new Date(last.createdAt).getTime())
    ? new Date(last.createdAt).getTime()
    : nowMs - defaultWindowMs(task);
  return { sinceIso: new Date(sinceMs).toISOString(), days: (nowMs - sinceMs) / DAY_MS };
}


// A collector factory bound to this run's repo context; the returned function is
// the `collectSignalsFor` seam the scheduler run and the executor call.
//
// `items` is the queue where the caller already fetched it (the scheduler run),
// so the run history of every task costs no read. `only` narrows a collection to
// the named signals — the scheduler's cheap first pass asks for `['runs']` alone
// and judges the run-history terms before anything else is collected.
export function collectSignalsForTask({ gh, repo, root, config, defaultBranch, items = null }) {
  return async function collectFor(task, now, item = null, { only = null } = {}) {
    const { collectSignals } = await import('./index.mjs');
    const { buildSignalContext } = await import('./context.mjs');
    const names = taskSignalNames(task.decl, task.terms);
    const packConfigFor = (packId) => config.packConfig?.[packId] ?? {};
    const nowIso = new Date(now).toISOString();
    const facts = itemFacts(item);
    const taskRef = { pack: task.pack, id: task.id };

    const rest = (only ? names.filter((n) => only.includes(n)) : names).filter((n) => n !== 'runs');
    // The history first, on its own: it needs no window and decides the window. It
    // is read only where something reads it — a run-history term, or a collector
    // that windows on it. A task reading nothing but the item it was created for
    // (the request implementer) pages no issue list at every pick.
    const windowless = new Set(['request']);
    const needsHistory = names.includes('runs') || rest.some((n) => !windowless.has(n));
    if (!needsHistory) return rest.length ? await collectSignals(gh, buildSignalContext({ root, repo, defaultBranch, now: nowIso, sinceIso: null, config, packConfigFor, item: facts, task: taskRef, items }), rest) : {};
    const history = buildSignalContext({ root, repo, defaultBranch, now: nowIso, sinceIso: null, config, packConfigFor, item: facts, task: taskRef, items });
    const { runs } = await collectSignals(gh, history, ['runs']);
    const window = windowFromRuns(task, runs?.error ? null : runs, now);
    const out = { runs: { ...runs, window } };
    if (!rest.length) return out;

    // The fleet aggregate is a full enumeration over a wider credential, so it is
    // built only when THIS task declares it and only where that credential exists.
    // Absent, the collector returns null and a fleet task's precondition declines
    // rather than crashing.
    let fleet = null;
    if (rest.includes('fleet')) {
      const { readFleet, makeFleetGh } = await import('./fleet.mjs');
      const fleetGh = makeFleetGh();
      if (fleetGh) {
        fleet = await readFleet(fleetGh, { owner: repo.split('/')[0], canonRepo: repo, sinceIso: window.sinceIso });
        if (fleet.error) console.log(`! fleet enumeration: ${fleet.error}`);
      } else {
        console.log('- this task declares the `fleet` signal but FLEET_GITHUB_TOKEN is not set');
      }
    }

    const ctx = buildSignalContext({
      root, repo, defaultBranch, now: nowIso, sinceIso: window.sinceIso, config, fleet, packConfigFor,
      // The occurrence's own facts, for the collector that reads one named object
      // rather than a window (the request read, PRINCIPLES.md).
      item: facts, task: taskRef, items,
    });
    return { ...out, ...(await collectSignals(gh, ctx, rest)) };
  };
}
=====CONTEXT=====
// The `ctx` every signal collector reads (docs/PRINCIPLES.md) —
// the already-resolved facts a collector may not go and fetch for itself, built
// once per collection and handed to `collectSignals`.
//
// Its own module so the construction is testable on its own: the collectors'
// `ctx.X ?? null` seam makes them unit-testable with a hand-built ctx, which is
// exactly why a key nothing here populates can read as "collector works" forever.
// Assert against THIS, not a hand-built shape.
//
// `root` is the Action-side checkout: the manifest version and the configured
// retention are read from it (signals/local.mjs), because a scheduled run already
// has the tree on disk and an API round-trip would buy nothing.

import { localSignalContext } from '../world/git.mjs';

// `item` is the OCCURRENCE the signals are being collected for, where the caller
// has one — the executor always does — as `itemFacts` reads it. Almost every
// collector reads a window of repo activity and ignores it; the `request`
// collector reads the single issue this item names, which is a fact no window can
// single out, and the `runs` collector excludes it from the task's history.
//
// `task` is `{ pack, id }`, the task whose run history is being read, and `items`
// the queue where the caller already fetched it (the scheduler run) — null where
// the collector reads it for itself (the executor at pick).
export function buildSignalContext({
  root, repo, defaultBranch, now, sinceIso, config, fleet = null, item = null, task = null, items = null, packConfigFor = () => ({}),
}) {
  const local = localSignalContext(root, { packIds: config.packs ?? [], packConfigFor });
  return {
    repo, defaultBranch, now, sinceIso, config, item, task, items,
    activePacks: config.packs, fleet,
    manifestVersion: local.manifestVersion,
    shipsReleasePipeline: local.shipsReleasePipeline,
    retentionDays: local.retentionDays,
  };
}

// The LOCAL-DISK half of the signal collectors' `ctx` (per-project-scheduling
// PRINCIPLES.md). Two collectors read facts off `ctx` that no GitHub read can
// supply — the shipped manifest version and whether this repo publishes at all
// (`release.manifestVersion`, `release.shipsPipeline`), and the configured log
// retention (`conversationLogs.retentionDays`). The scheduler runs Action-side
// INSIDE the repo checkout, so both are readable from the checkout itself:
// no API call, no rate budget, no base64 round-trip, and the tree read is the
// same tree the run would ship.
//
// This deliberately sits BESIDE the collectors rather than inside them. The
// collectors stay pure over an injected `ctx` (`ctx.X ?? null`), so the whole
// signal layer still unit-tests against a fake `gh` with no repo on disk; this
// module is the one place that touches the filesystem, and signals/context.mjs folds its
// result into the ctx it hands the collectors.

import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

// Where a repo's own packs live. One definition, shared by the `localPacks`
// collector's path test and the fleet reader's per-member window scan, so "where
// a local pack lives" cannot drift between the two. Spelled '/'-separated because
// both readers match paths that came off git or the GitHub API.
export const LOCAL_PACK_ROOT = '.claudinite/local/packs/';

// Where a browser-extension manifest may sit, in the order the retired gate
// probed them (recovered from the pack's deleted run_daily gate): the first one
// carrying a `version` wins. Absent/unparsable/versionless → null, which the
// consuming precondition reads as "no manifest version to judge".
const MANIFEST_PATHS = ['manifest.json', 'src/manifest.json', 'public/manifest.json', 'dist/manifest.json'];

function readManifestVersion(root) {
  for (const path of MANIFEST_PATHS) {
    let json;
    try { json = JSON.parse(readFileSync(join(root, path), 'utf8')); } catch { continue; }
    if (json?.version) return String(json.version);
  }
  return null;
}

// Does this repo PUBLISH — does it carry the release orchestrator (by `name:`, since
// a repo may host the pipeline's own reusable workflows at the same paths without
// being a publisher, as Claudinite's core tree does) or a release config? Either is
// enough, and the pair is the release standard's own test.
//
// The spelling lives here rather than being imported because the engine depends on no
// pack; the release pack's own SHIPS_PIPELINE_* regexes are the other copy, and the
// drift test beside them fails if the two disagree.
const SHIPS_PIPELINE_TEXT = /^(?:name:\s*['"]?(?:Release to Chrome Store|Release)['"]?\s*|manifest_path=.*)$/m;

function readShipsReleasePipeline(root) {
  const candidates = [];
  try {
    for (const e of readdirSync(join(root, '.github/workflows'), { withFileTypes: true })) {
      if (e.isFile() && /\.ya?ml$/.test(e.name)) candidates.push(join('.github/workflows', e.name));
    }
  } catch { /* no workflows directory — the release config may still say it ships */ }
  candidates.push('.github/release.config');
  return candidates.some((rel) => {
    try { return SHIPS_PIPELINE_TEXT.test(readFileSync(join(root, rel), 'utf8')); } catch { return false; }
  });
}

// The log-retention window, in days, from the declared packs' entry config
// (`retention_days` in .claudinite-settings.json). Read through the caller's
// existing per-pack config reader rather than a second settings parser, and
// keyed by the PARAMETER, not by a pack name — core does not name the pack that
// happens to declare it. First declared pack carrying a numeric value wins.
function readRetentionDays(packIds, packConfigFor) {
  for (const id of packIds) {
    const value = packConfigFor(id)?.retention_days;
