  // is a world that never reaches quiescence and so never advances the clock the
  // waiter is waiting for.
  const park = (promise) => {
    waiting += 1;
    return Promise.resolve(promise).then(
      (v) => { waiting -= 1; return v; },
      (e) => { waiting -= 1; throw e; },
