// measured over the dirs a real sweep asks for, by defeating the module memo with
// a cache-busting import per iteration.
import { readFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { execFileSync } from 'node:child_process';

const root = '/home/user/Claudinite/.claude/worktrees/agent-ac03403e66586c0ba';
const dirs = execFileSync('git', ['ls-files', '*declared-checks.json'], { cwd: root, encoding: 'utf8' })
  .split('\n').filter(Boolean).map((p) => join(root, p.replace(/\/declared-checks\.json$/, '')));

let bytes = 0, specs = 0;
for (const d of dirs) { const t = readFileSync(join(d, 'declared-checks.json'), 'utf8'); bytes += t.length; specs += JSON.parse(t).length; }

const ITER = 20;
const t0 = process.hrtime.bigint();
for (let i = 0; i < ITER; i++) {
  const { loadDeclaredChecks } = await import(`/home/user/Claudinite/.claude/worktrees/agent-ac03403e66586c0ba/engine/checks/helpers/pattern-rules.mjs?bust=${i}`);
  for (const d of dirs) loadDeclaredChecks(d);
}
const ms = Number(process.hrtime.bigint() - t0) / 1e6;
console.log(`${dirs.length} dirs, ${specs} specs, ${bytes} bytes`);
console.log(`cold full-set load: ${(ms / ITER).toFixed(2)} ms per pass (${ITER} passes, module re-eval included)`);

