1	// Signal collection for ONE task (docs/PRINCIPLES.md): exactly that
2	// task's declared union, collected at the moment a verdict is asked for. Two
3	// callers ask — the scheduler run at every tick (a read it cannot make fails open
4	// there) and the executor at pick, which re-derives rather than trusting the
5	// tick's answer forward.
6	//
7	// THE RUN HISTORY COMES FIRST, always: the `runs` bundle is what the cadence
8	// terms read, and it is also what sets the WINDOW every other collector reads
9	// over — since this task's newest run started, so a task reads exactly what moved
10	// since it last looked, and one that declined for a week then sees the week. With
11	// no run in the horizon the window is the task's own cadence (a day for a task
12	// stating none) plus an hour of slack. Overlap at the seam — a run's own duration
13	// — is absorbed by the preconditions' own dedupe, as the old fixed lookback's was.
14	
15	import { itemFacts } from '../items/work-item.mjs';
16	import { taskSignalNames } from '../contract/task-contract.mjs';
17	import { DAY_MS, defaultWindowMs, windowDaysOf } from '../contract/precondition.mjs';
18	
19	// Republished from the contract that owns them: a caller reading a task's window
20	// off its collected signals asks the collector, not two modules.
21	export { defaultWindowMs, windowDaysOf };
22	
23	// The window, from the run history: `{ sinceIso, days }`. The newest run that
24	// actually ran — a `rejected` item declined at pick and did nothing, so it does not
25	// move the seam — anchors it at its start; none in the horizon falls back to the
26	// task's default.
27	export function windowFromRuns(task, runs, now) {
28	  const nowMs = new Date(now).getTime();
29	  const last = (runs?.list ?? []).find((r) => r.outcome !== 'obsolete');
30	  const sinceMs = last && Number.isFinite(new Date(last.createdAt).getTime())
31	    ? new Date(last.createdAt).getTime()
32	    : nowMs - defaultWindowMs(task);
33	  return { sinceIso: new Date(sinceMs).toISOString(), days: (nowMs - sinceMs) / DAY_MS };
34	}
35	
36	
37	// A collector factory bound to this run's repo context; the returned function is
38	// the `collectSignalsFor` seam the scheduler run and the executor call.
39	//
40	// `items` is the queue where the caller already fetched it (the scheduler run),
41	// so the run history of every task costs no read. `only` narrows a collection to
42	// the named signals — the scheduler's cheap first pass asks for `['runs']` alone
43	// and judges the run-history terms before anything else is collected.
44	const __mods = Promise.all([import('./index.mjs'), import('./context.mjs')]);
45	export function collectSignalsForTask({ gh, repo, root, config, defaultBranch, items = null }) {
46	  return async function collectFor(task, now, item = null, { only = null } = {}) {
47	    const [{ collectSignals }, { buildSignalContext }] = await __mods;
48	    const names = taskSignalNames(task.decl, task.terms);
49	    const packConfigFor = (packId) => config.packConfig?.[packId] ?? {};
50	    const nowIso = new Date(now).toISOString();
51	    const facts = itemFacts(item);
52	    const taskRef = { pack: task.pack, id: task.id };
53	
54	    const rest = (only ? names.filter((n) => only.includes(n)) : names).filter((n) => n !== 'runs');
55	    // The history first, on its own: it needs no window and decides the window. It
56	    // is read only where something reads it — a run-history term, or a collector
57	    // that windows on it. A task reading nothing but the item it was created for
58	    // (the request implementer) pages no issue list at every pick.
59	    const windowless = new Set(['request']);
60	    const needsHistory = names.includes('runs') || rest.some((n) => !windowless.has(n));
61	    if (!needsHistory) return rest.length ? await collectSignals(gh, buildSignalContext({ root, repo, defaultBranch, now: nowIso, sinceIso: null, config, packConfigFor, item: facts, task: taskRef, items }), rest) : {};
62	    const history = buildSignalContext({ root, repo, defaultBranch, now: nowIso, sinceIso: null, config, packConfigFor, item: facts, task: taskRef, items });
63	    const { runs } = await collectSignals(gh, history, ['runs']);
64	    const window = windowFromRuns(task, runs?.error ? null : runs, now);
65	    const out = { runs: { ...runs, window } };
66	    if (!rest.length) return out;
67	
68	    // The fleet aggregate is a full enumeration over a wider credential, so it is
69	    // built only when THIS task declares it and only where that credential exists.
70	    // Absent, the collector returns null and a fleet task's precondition declines
71	    // rather than crashing.
72	    let fleet = null;
73	    if (rest.includes('fleet')) {
74	      const { readFleet, makeFleetGh } = await import('./fleet.mjs');
75	      const fleetGh = makeFleetGh();
76	      if (fleetGh) {
77	        fleet = await readFleet(fleetGh, { owner: repo.split('/')[0], canonRepo: repo, sinceIso: window.sinceIso });
78	        if (fleet.error) console.log(`! fleet enumeration: ${fleet.error}`);
79	      } else {
80	        console.log('- this task declares the `fleet` signal but FLEET_GITHUB_TOKEN is not set');
81	      }
82	    }
83	
84	    const ctx = buildSignalContext({
85	      root, repo, defaultBranch, now: nowIso, sinceIso: window.sinceIso, config, fleet, packConfigFor,
86	      // The occurrence's own facts, for the collector that reads one named object
87	      // rather than a window (the request read, PRINCIPLES.md).
88	      item: facts, task: taskRef, items,
89	    });
90	    return { ...out, ...(await collectSignals(gh, ctx, rest)) };
