let MODE = 'all';

function snapshot(root, build) {
  const ctx = build({ root, mode: MODE });
  const plain = {};
  for (const k of Object.keys(ctx).sort()) if (typeof ctx[k] !== 'function') plain[k] = ctx[k];
  plain.__reads = Object.fromEntries(ctx.allFiles.map((f) => [f, ctx.read(f)]));
  plain.__exists = Object.fromEntries(ctx.allFiles.map((f) => [f, ctx.exists(f)]));
  plain.__readBase = Object.fromEntries(ctx.allFiles.map((f) => [f, ctx.readBase(f)]));
  plain.__added = Object.fromEntries(ctx.changedFiles.map((f) => [f, ctx.addedLines(f)]));
  plain.__removed = Object.fromEntries(ctx.changedFiles.map((f) => [f, ctx.removedLines(f)]));
  plain.__vendored = ctx.allFiles.filter((f) => !ctx.files.includes(f));
  plain.__commitsWithFiles = ctx.commitsWithFiles();
  plain.__merges = ctx.introducedMergeCommits();
  plain.__grep = ctx.grepTracked('line 3');
  return JSON.stringify(plain, null, 1)
    .split(root).join('<root>')
    .replace(/\b[0-9a-f]{7,40}\b/g, '<sha>')
    .replace(/\d{4}-\d\d-\d\dT[\d:+-]+/g, '<date>');
}

let fails = 0;
let checked = 0;
for (const { name, shape, after } of SHAPES) {
  for (const mode of ['all', 'changed']) {
    MODE = mode;
    const rOld = makeOld(structuredClone(shape)); if (after) after(rOld, gitOld);
    const rNew = makeNew(structuredClone(shape)); if (after) after(rNew, gitNew);
    let snaps;
    try {
      snaps = {
        'old fixture / old context': snapshot(rOld, ctxOld),
        'old fixture / new context': snapshot(rOld, ctxNew),
        'new fixture / old context': snapshot(rNew, ctxOld),
        'new fixture / new context': snapshot(rNew, ctxNew),
      };
    } finally { cleanup(rOld); cleanup(rNew); }
    const ref = snaps['old fixture / old context'];
    const bad = Object.entries(snaps).filter(([, s]) => s !== ref);
    checked++;
    if (!bad.length) { console.log(`  ok   ${name} [${mode}]`); continue; }
    fails++;
    console.log(`  FAIL ${name} [${mode}] — diverged: ${bad.map(([k]) => k).join(', ')}`);
    const la = ref.split('\n');
    const lb = bad[0][1].split('\n');
    for (let i = 0, shown = 0; i < Math.max(la.length, lb.length) && shown < 8; i++) {
      if (la[i] !== lb[i]) { console.log(`    ref: ${la[i]}\n    got: ${lb[i]}`); shown++; }
    }
  }
}
console.log(fails ? `\n${fails}/${checked} combinations DIVERGED` : `\nall ${checked} shape/mode combinations: every path byte-identical`);
process.exit(fails ? 1 : 0);

