7	import { SETTINGS_FILE, LEGACY_SETTINGS_FILE, settingsPath } from '../../settings-file.mjs';
8	import { isVersion } from '../../version.mjs';
9	
10	function sh(root, cmd, args, { allowFail = false, input = undefined, timeout = undefined } = {}) {
11	  const r = spawnSync(cmd, args, { cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, input, timeout });
12	  if (r.status !== 0 && !allowFail) {
13	    throw new Error(`${cmd} ${args.join(' ')} failed (${r.status}): ${r.stderr}`);
14	  }
15	  return r.status === 0 ? r.stdout : null;
16	}
17	
18	const git = (root, ...args) => sh(root, 'git', args);
19	const gitTry = (root, ...args) => sh(root, 'git', args, { allowFail: true });
20	
21	// The base branch this repo's work is judged against, in preference order.
22	// Exported because the CI entry point (../ci-work-scope.mjs) fetches these same
23	// refs before a context is built at all — one list, so what CI fetches and what a
24	// context resolves can never name different branches.
25	export const BASE_REF_CANDIDATES = ['origin/main', 'origin/master', 'main', 'master'];
26	
27	// All four candidates in ONE subprocess. `cat-file --batch-check` takes revisions on
28	// stdin and answers each independently — `<sha> commit <size>` for one that resolves,
29	// `<input> missing` for one that does not — so it is the same revision parser
30	// `rev-parse --verify` uses, `^{commit}` peeling included, asked four questions at
31	// once instead of four times. A repo whose base is a local `main` (every check fixture,
32	// and any clone without a remote) missed on both `origin/` candidates first and paid
33	// three spawns for an answer that now costs one.
34	function resolveBaseRef(root) {
35	  const answers = (sh(root, 'git', ['cat-file', '--batch-check'],
36	    { allowFail: true, input: `${BASE_REF_CANDIDATES.map((ref) => `${ref}^{commit}`).join('\n')}\n` }) || '')
37	    .split('\n');
38	  // Object-id length is the repo's hash algorithm's, not a constant — sha1 and sha256
39	  // repos both answer here, and only the `commit` word decides.
40	  return BASE_REF_CANDIDATES.find((_, i) => /^[0-9a-f]+ commit /.test(answers[i] ?? '')) ?? null;
41	}
42	
43	const FETCH_TIMEOUT_MS = 8000;
44	const FETCH_WINDOW_MS = 5 * 60_000;
45	
46	// A remote-tracking base ref is only as fresh as the last fetch, and a cloud session's
47	// clone freezes it at container-creation time — so every commit the base branch gained
48	// since lands inside `mergeBase..HEAD` and gets billed to the work. That is a wrong
49	// verdict, not a stale one: the delta rules (squash-merge-history above all, a *blocking*
50	// rule) report other people's commits as introduced by this change, and `--changed`
51	// widens to files the change never touched. Refreshing the ref once per run is what makes
52	// "the work" mean the work.
53	//
54	// Best-effort by construction — no network, no remote, a lock held, a slow server: the
55	// fetch fails or times out and the run continues against the ref as it stands, exactly as
56	// before this existed. It writes ONLY the remote-tracking ref (explicit refspec, no tags):
57	// no local branch, no index, no working tree, nothing the session could be surprised by.
58	// Set CLAUDINITE_CHECKS_NO_FETCH=1 to skip it (sealed sandboxes, or to pin a base).
59	//
60	// And it runs once per freshness window, not once per run: the Stop hook builds a context
61	// every turn with tracked changes, and the fetch is that path's dominant wall-clock cost
62	// (~0.7s healthy, 8s timeout when the network is not). A marker in the git dir records
63	// which ref was refreshed and when; a run inside the window trusts it and skips. The
64	// marker is PER-REF on purpose — a fetch of some other ref (or a marker left by one) says
65	// nothing about this base's freshness — and the staleness the window admits is the same
66	// class the fetch's own failure tolerance already accepts, now bounded by the window.
67	function refreshBaseRef(root, ref) {
68	  if (!ref || process.env.CLAUDINITE_CHECKS_NO_FETCH === '1') return;
69	  const m = /^([^/]+)\/(.+)$/.exec(ref);
70	  if (!m) return; // a local branch is already as current as the checkout — nothing to fetch
71	  const markerRel = (gitTry(root, 'rev-parse', '--git-path', 'claudinite-base-refresh.json') || '').trim();
72	  const marker = markerRel ? resolve(root, markerRel) : null;
73	  if (marker) {
74	    try {
75	      const last = JSON.parse(readFileSync(marker, 'utf8'));
76	      if (last.ref === ref && Date.now() - last.at < FETCH_WINDOW_MS) return;
77	    } catch { /* no marker (or an unreadable one) means no known freshness — fetch */ }
78	  }
79	  const [, remote, branch] = m;
80	  const fetched = sh(root, 'git', ['fetch', '--quiet', '--no-tags', remote,
