// Does `diff --name-status`, with its D entries dropped and a rename's destination
// taken, reproduce `diff --name-only --diff-filter=d` exactly — list AND order —
// and do its D entries reproduce `--diff-filter=D`? Fuzzed over random trees with
// renames, deletions, additions and edits, in both directions of the sort.
import { mkdtempSync, mkdirSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { spawnSync } from 'node:child_process';
import { removeTree } from '/home/user/Claudinite/.claude/worktrees/agent-a3e17674cbbdd3bce/engine/remove-tree.mjs';

const ENV = {
  ...process.env,
  GIT_AUTHOR_NAME: 'test', GIT_AUTHOR_EMAIL: 't@t', GIT_COMMITTER_NAME: 'test', GIT_COMMITTER_EMAIL: 't@t',
  GIT_CONFIG_COUNT: '1', GIT_CONFIG_KEY_0: 'commit.gpgsign', GIT_CONFIG_VALUE_0: 'false',
};
const git = (root, ...args) => {
  const r = spawnSync('git', args, { cwd: root, env: ENV, encoding: 'utf8' });
  if (r.status !== 0) throw new Error(`git ${args.join(' ')}: ${r.stderr}`);
  return r.stdout;
};
const lines = (s) => s.split('\n').filter(Boolean);
const write = (root, p, c) => { mkdirSync(join(root, dirname(p)), { recursive: true }); writeFileSync(join(root, p), c); };

let seed = Number(process.argv[2] ?? 12345);
const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
const pick = (a) => a[Math.floor(rnd() * a.length)];
const WORDS = ['aaa', 'mmm', 'zzz', 'Alpha', 'zebra', 'x', 'dir one/a', 'dir two/b', 'sub/deep/c', 'ünïcode', 'with space', '0', '~tilde', 'a-b'];
const body = (n) => Array.from({ length: 10 }, (_, i) => `line ${i} of ${n}\n`).join('');

let fails = 0;
const ROUNDS = Number(process.argv[3] ?? 150);
for (let round = 0; round < ROUNDS; round++) {
  const root = mkdtempSync(join(tmpdir(), 'fuzz-diff-'));
  try {
    git(root, 'init', '-q', '-b', 'main');
    const baseNames = [...new Set(Array.from({ length: 2 + Math.floor(rnd() * 6) }, () => `${pick(WORDS)}${Math.floor(rnd() * 5)}.txt`))];
    for (const n of baseNames) write(root, n, body(n));
    git(root, 'add', '-A');
    git(root, 'commit', '-q', '-m', 'seed');
    git(root, 'checkout', '-q', '-b', 'feature');

    const survivors = [...baseNames];
    const ops = [];
    for (let i = 0; i < 1 + Math.floor(rnd() * 4); i++) {
      const kind = pick(['rename', 'rename', 'delete', 'edit', 'add']);
      if (kind === 'rename' && survivors.length) {
        const from = pick(survivors);
        const to = `${pick(WORDS)}${Math.floor(rnd() * 9)}-renamed.txt`;
        if (survivors.includes(to)) continue;
        git(root, 'mv', from, to);
        survivors.splice(survivors.indexOf(from), 1); survivors.push(to);
        ops.push(`mv ${from} -> ${to}`);
      } else if (kind === 'delete' && survivors.length > 1) {
        const p = pick(survivors);
        git(root, 'rm', '-q', p);
        survivors.splice(survivors.indexOf(p), 1);
        ops.push(`rm ${p}`);
      } else if (kind === 'edit' && survivors.length) {
        const p = pick(survivors);
        write(root, p, `${body(p)}edit ${rnd()}\n`);
        ops.push(`edit ${p}`);
      } else {
        const p = `${pick(WORDS)}${Math.floor(rnd() * 9)}-new.txt`;
        write(root, p, body(p));
        if (!survivors.includes(p)) survivors.push(p);
        ops.push(`add ${p}`);
      }
    }
    git(root, 'add', '-A');
    git(root, 'commit', '-q', '-m', 'change');

    const nameOnly = lines(git(root, 'diff', '--name-only', '--diff-filter=d', 'main'));
    const onlyDeleted = lines(git(root, 'diff', '--name-only', '--diff-filter=D', 'main'));
    const entries = lines(git(root, 'diff', '--name-status', 'main')).map((l) => l.split('\t'));
    const rebuilt = entries.filter(([s]) => !s.startsWith('D')).map((e) => e[e.length - 1]);
    const rebuiltDeleted = entries.filter(([s]) => s.startsWith('D')).map((e) => e[1]);
    const renames = entries.filter(([s]) => s.startsWith('R') || s.startsWith('C')).length;

    if (JSON.stringify(rebuilt) !== JSON.stringify(nameOnly) || JSON.stringify(rebuiltDeleted) !== JSON.stringify(onlyDeleted)) {
      fails++;
      console.log(`DIVERGED round ${round} (renames=${renames})\n  ops: ${ops.join('; ')}`);
      console.log(`  name-only: ${JSON.stringify(nameOnly)}\n  rebuilt  : ${JSON.stringify(rebuilt)}`);
      console.log(`  del-only : ${JSON.stringify(onlyDeleted)}\n  rebuiltD : ${JSON.stringify(rebuiltDeleted)}`);
      if (fails > 5) break;
    }
  } finally { removeTree(root); }
}
console.log(fails ? `\n${fails} divergence(s)` : `\n${ROUNDS} random histories: --name-status reconstructs both lists exactly, order included`);
process.exit(fails ? 1 : 0);

