  const writable = build({ root, mode: MODE });
  writable.files = ['SENTINEL'];
  writable.commits = ['SENTINEL-COMMIT'];
  plain.__assigned = { files: writable.files, commits: writable.commits, alsoChanged: writable.changedFiles };

  return JSON.stringify(plain, null, 1)
    .split(root).join('<root>')
    .replace(/\b[0-9a-f]{7,40}\b/g, '<sha>')
    .replace(/\d{4}-\d\d-\d\dT[\d:+-]+/g, '<date>');
}

let fails = 0;
let checked = 0;
for (const { name, shape, after } of SHAPES) {
