    MODE = mode;
    const root = makeRepo(structuredClone(shape));
    if (after) after(root, git);
    let a; let b;
    try {
      a = snapshot(root, ctxEager);
      b = snapshot(root, ctxLazy);
    } finally { cleanup(root); }
    checked++;
    if (a === b) { console.log(`  ok   ${name} [${mode}]`); continue; }
    fails++;
    console.log(`  FAIL ${name} [${mode}]`);
    const la = a.split('\n'); const lb = b.split('\n');
    for (let i = 0, shown = 0; i < Math.max(la.length, lb.length) && shown < 10; i++) {
      if (la[i] !== lb[i]) { console.log(`    eager: ${la[i]}\n    lazy : ${lb[i]}`); shown++; }
    }
  }
}
console.log(fails ? `\n${fails}/${checked} combinations DIVERGED` : `\nall ${checked} shape/mode combinations: every path byte-identical`);
process.exit(fails ? 1 : 0);

