  // No signals declared, so nothing is collected — the ctx build is what we are after.
  const { buildSignalContext } = await import('/home/user/Claudinite/.claude/worktrees/agent-ad310cc770548756c/packs/claudinite-tasks/src/signals/context.mjs');
  await collect(task, new Date().toISOString(), { number: 1 });
  return buildSignalContext; // unused; the read below is the real assertion
