const { localSignalContext } = await import('/home/user/Claudinite/.claude/worktrees/agent-ad310cc770548756c/packs/claudinite-tasks/src/world/git.mjs');
const before = localSignalContext(root, { packIds: [] }).manifestVersion;

writeFileSync(join(root, 'manifest.json'), JSON.stringify({ version: '2.0.0' })); // the code_work step

const { buildSignalContext } = await import('/home/user/Claudinite/.claude/worktrees/agent-ad310cc770548756c/packs/claudinite-tasks/src/signals/context.mjs');
const ctxOf = (collectorWiring) => {
  const local = collectorWiring;
  return buildSignalContext({ root, repo: 'o/r', defaultBranch: 'main', now: new Date().toISOString(), sinceIso: null, config, local });
};
// A per-pick collector re-reads at construction; a per-run one froze at its own.
const freshLocal = localSignalContext(root, { packIds: [] });
console.log('before code_work   :', before);
console.log('per-pick collector :', ctxOf(freshLocal).manifestVersion);
console.log('per-run collector  :', ctxOf(await (async () => { /* the memo the run built before the rewrite */ return { manifestVersion: before, shipsReleasePipeline: false, retentionDays: null }; })()).manifestVersion);
void perRun;

