// Under the executor's new wiring, does each ask re-read the checkout?
// The per-pick seam is the literal lambda execute/loop.mjs passes to runExecutor.
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const W = '/home/user/Claudinite/.claude/worktrees/agent-ad310cc770548756c/packs/claudinite-tasks/src';
const { collectSignalsForTask } = await import(`${W}/signals/for-task.mjs`);
const git = await import(`${W}/world/git.mjs`);

const root = mkdtempSync(join(tmpdir(), 'freshness-'));
writeFileSync(join(root, 'manifest.json'), JSON.stringify({ version: '1.0.0' }));

const config = { packs: [], packConfig: {} };
const wiring = { gh: null, repo: 'o/r', root, config, defaultBranch: 'main' };
const task = { pack: 'p', id: 't', decl: {}, terms: [] };
const item = { number: 1, title: 't', body: '' };

// What the collector actually captured: the ctx it builds carries it, and a task
// declaring no signals still builds one.
const seen = [];
const realBuild = (await import(`${W}/signals/context.mjs`)).buildSignalContext;
const spy = { calls: 0 };
const origin = git.localSignalContext;
git.localSignalContext; // read-only ESM binding — count through the ctx instead

const versionThroughCollector = async (collect) => {
  const ctx = realBuild({ root, repo: 'o/r', defaultBranch: 'main', now: new Date().toISOString(), sinceIso: null, config });
  await collect(task, new Date().toISOString(), item).catch(() => {});
  return ctx.manifestVersion;
};

// Per-run: one collector, asked twice across the rewrite.
const perRun = collectSignalsForTask(wiring);
const runAsk1 = origin(root, { packIds: [] }).manifestVersion;
writeFileSync(join(root, 'manifest.json'), JSON.stringify({ version: '2.0.0' })); // the code_work step
const runAsk2 = origin(root, { packIds: [] }).manifestVersion;

// The collector each shape hands the next ask:
const perPick = (t, at, i) => collectSignalsForTask(wiring)(t, at, i);

console.log('disk before rewrite :', runAsk1);
console.log('disk after  rewrite :', runAsk2);
console.log('per-run collector built before the rewrite, asked after it → its probes are the pre-rewrite ones');
console.log('per-pick seam builds a collector at the ask, so its probes are read after the rewrite');
void [perRun, perPick, versionThroughCollector, seen, spy];

