// The hazard, demonstrated: a collector built for the whole drain answers the
// second pick from the pre-rewrite tree; one built at the ask does not.
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const W = '/home/user/Claudinite/.claude/worktrees/agent-ad310cc770548756c/packs/claudinite-tasks/src';
const { collectSignalsForTask } = await import(`${W}/signals/for-task.mjs`);

const root = mkdtempSync(join(tmpdir(), 'freshness-'));
writeFileSync(join(root, 'manifest.json'), JSON.stringify({ version: '1.0.0' }));

const config = { packs: [], packConfig: {} };
const wiring = { gh: null, repo: 'o/r', root, config, defaultBranch: 'main' };
const task = { pack: 'p', id: 't', decl: {}, terms: [] };
const item = { number: 1, title: 't', body: '' };
const at = new Date().toISOString();

const probes = () => globalThis.__PROBES ?? [];
const since = (n) => probes().slice(n);

// --- the per-run shape (what the executor did before) ---------------------
const perRun = collectSignalsForTask(wiring);
console.log('per-run collector built, probes so far:', JSON.stringify(probes()));
writeFileSync(join(root, 'manifest.json'), JSON.stringify({ version: '2.0.0' })); // a code_work step
const mark = probes().length;
await perRun(task, at, item);
console.log('per-run, asked after the rewrite — new probes:', JSON.stringify(since(mark)));

// --- the per-pick seam (execute/loop.mjs's lambda) -------------------------
const perPick = (t, a, i) => collectSignalsForTask(wiring)(t, a, i);
const mark2 = probes().length;
await perPick(task, at, item);
console.log('per-pick, asked after the rewrite — new probes:', JSON.stringify(since(mark2)));

