const before = (fn) => { let v, done = false; return () => (done ? v : (done = true, v = fn())); };
const after  = (fn) => { let value, derived = false; return () => { if (!derived) { value = fn(); derived = true; } return value; }; };
for (const [name, once] of [["old shape", before], ["new shape", after]]) {
  let calls = 0;
  const g = once(() => { calls++; throw new Error("boom"); });
  const read = () => { try { g(); return "threw"; } catch { return "threw"; } };
  const first = (() => { try { g(); return "returned " + g(); } catch { return "threw"; } })();
  let second;
  try { second = "returned " + JSON.stringify(g()); } catch { second = "threw"; }
  console.log(`  ${name}: first read ${first}, second read ${second} (fn called ${calls}x)`);
}'

